WITH valid AS (SELECT id, session_id, event_type, page, event_time, duration_sec, WEEKOFYEAR(event_time) AS event_time_weekofyear, DATEDIFF(CURRENT_DATE(), event_time) / 365 AS years_since_event_time, COALESCE(page, 'OTHER') AS page_clean FROM web_events WHERE page IS NOT NULL), ranked AS (SELECT id, session_id, page, event_time, event_time_weekofyear, years_since_event_time FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_time_weekofyear DESC NULLS LAST, id) AS dedup_rank FROM valid) x WHERE dedup_rank = 1), filtered AS (SELECT id, session_id, page, event_time, event_time_weekofyear, years_since_event_time, CASE WHEN years_since_event_time >= 63 THEN 'High' WHEN years_since_event_time >= 25 THEN 'Medium' ELSE 'Low' END AS years_since_event_time_level FROM ranked WHERE event_time >= TIMESTAMP '2023-06-04 00:00:00' AND page IS NOT NULL), latest AS (SELECT * FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY session_id, page ORDER BY event_time DESC, id) = 1) SELECT id, session_id, page, event_time_weekofyear, years_since_event_time, years_since_event_time_level FROM latest ORDER BY event_time_weekofyear DESC NULLS LAST, id DESC;
